from fastapi.security import APIKeyQuery, APIKeyHeader, APIKeyCookie, HTTPBearer, HTTPDigest, OpenIdConnect
from fastapi.testclient import TestClient

app = FastAPI()

api_key_query = APIKeyQuery(name="query_key")
api_key_header = APIKeyHeader(name="header_key")
api_key_cookie = APIKeyCookie(name="cookie_key")
http_bearer = HTTPBearer()
http_digest = HTTPDigest()
oidc = OpenIdConnect()

@app.get("/query")
async def read_query(key: str = Depends(api_key_query)):
    return {"key": key}

@app.get("/header")
async def read_header(key: str = Depends(api_key_header)):
    return {"key": key}

@app.get("/cookie")
async def read_cookie(key: str = Depends(api_key_cookie)):
    return {"key": key}

@app.get("/bearer")
async def read_bearer(token: str = Depends(http_bearer)):
    return {"token": token}

@app.get("/digest")
async def read_digest(credentials: str = Depends(http_digest)):
    return {"credentials": credentials}

@app.get("/oidc")
async def read_oidc(token: str = Depends(oidc)):
    return {"token": token}

client = TestClient(app)

def test_security_status_codes():
    endpoints = [
        ("/query", "APIKeyQuery"),
        ("/header", "APIKeyHeader"),
        ("/cookie", "APIKeyCookie"),
        ("/bearer", "HTTPBearer"),
        ("/digest", "HTTPDigest"),
        ("/oidc", "OpenIdConnect"),
    ]

    for path, name in endpoints:
        response = client.get(path)
        print(f"{name}: status_code={response.status_code}")
        # The issue says these should be 401, but currently are 403 (except some)
        # We want to assert they are 401. If they are 403, the test fails, which is what we want for repro.
        assert response.status_code == 401, f"{name} returned {response.status_code} instead of 401"

if __name__ == "__main__":
    try:
        test_security_status_codes()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Assertion failed: {e}")
        exit(1)
